def icon(name: str, cls: str = "w-5 h-5") -> Markup:
    """Render an inline Heroicon SVG."""
    paths = _ICONS.get(name)
    if not paths:
        return Markup("")
    return Markup(
        '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"'
        ' stroke-width="1" stroke="currentColor" class="' + cls + '"'
        ' aria-hidden="true">'
        + paths
        + "</svg>"
    )
